/// every feature hook slot of this crate and the crates below, with whether it is filled
pub fn feature_hook_slots() -> Vec<(&'static str, bool)> {
    fn state<T>(slot: &'static crate::core::feature_hooks::feature_hooks::FeatureHookSlot<T>) -> (&'static str, bool) {
        (slot.name(), slot.is_installed())
    }
    let mut slots: Vec<(&'static str, bool)> = Vec::new();
    slots.extend(riseonly_data_guides::feature_hook_slots());
    slots.push(state(&crate::core::ui::rich_text::document::rise_document_editor_hooks::RISE_DOCUMENT_EDITOR_HOOKS));
    slots.push(state(&crate::core::widgets::sheets::report_evidence_picker_hooks::REPORT_EVIDENCE_PICKER_HOOKS));
    slots.push(state(&crate::modules::camera::components::feed_media_picker_page_hooks::FEED_MEDIA_PICKER_PAGE_HOOKS));
    slots.push(state(&crate::modules::media_picker::ui::media_picker_caption_bar_hooks::MEDIA_PICKER_CAPTION_BAR_HOOKS));
    slots.push(state(&crate::modules::music::widgets::music_cover_picker_hooks::MUSIC_COVER_PICKER_HOOKS));
    slots.push(state(&crate::modules::post::components::post::post_list_player_layer_hooks::POST_LIST_PLAYER_LAYER_HOOKS));
    slots.push(state(&crate::modules::stickers::components::sticker_asset_composer_emoji_hooks::STICKER_ASSET_COMPOSER_EMOJI_HOOKS));
    slots.push(state(&crate::modules::story::components::story_composer_picker_hooks::STORY_COMPOSER_PICKER_HOOKS));
    slots.push(state(&crate::modules::user::components::profile_content::pages::grid_posts::post_row_warm_anchor_hooks::POST_ROW_WARM_ANCHOR_HOOKS));
    slots.push(state(&crate::modules::user::components::profile_content::profile_content_goals_hooks::PROFILE_CONTENT_GOALS_HOOKS));
    slots
}
